    localparam STATE_LEFT = 1'b0;
    localparam STATE_RIGHT = 1'b1;
    // The current state of the finite state machine. Registered.
    reg state;
    // The next state of the finite state machine, computed combinatorially
    // based on the current state and the inputs.
    wire next_state = (state == STATE_LEFT) ?
        (bump_right ? STATE_RIGHT : STATE_LEFT) :
        (bump_left ? STATE_LEFT : STATE_RIGHT);
