// Moore state machine, one bit outputs for each state, one bit per input
// (regardless of what the function of the input is). This models the
// Lemmings' brains, which include a fairly complex decision-making
// function based on the current state and the current inputs.
module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    output reg walk_left,
    output reg walk_right
);
    reg [1:0] state;
    always @(posedge clk) begin
        if (areset) begin
            state <= 2'd0;
            walk_left <= 1'd1;
            walk_right <= 1'd0;
        end else begin
            case (state)
                2'd0: begin
                    if (bump_left) begin
                        state <= 2'd1;
                        walk_left <= 1'd0;
                        walk_right <= 1'd1;
                    end else if (bump_right) begin
                        state <= 2'd1;
                        walk_left <= 1'd1;
                        walk_right <= 1'd0;
                    end
                end
                2'd1: begin
                    if (bump_left) begin
                        state <= 2'd0;
                        walk_left <= 1'd1;
                        walk_right <= 1'd0;
                    end else if (bump_right) begin
                        state <= 2'd0;
                        walk_left <= 1'd0;
                        walk_right <= 1'd1;
                    end
                end
            endcase
        end
    end
endmodule

